code.java:
class Solution {
    public int longestString(int x,int y,int z){
        int blocks=2*Math.min(x,y)+(x==y?0:1)+z;
        return blocks*2;
    }
}

code.kotlin:
class Solution {
    fun longestString(x:Int,y:Int,z:Int):Int{
        return (2*minOf(x,y)+(if(x==y)0 else 1)+z)*2
    }
}

